INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (165, 'Z02-W30-002', '沙棘人参养肝合剂', '200ml/瓶', '委托加工', '每瓶装200ml(相当于中药饮片128g)', '湘药制备字Z20230858000', '健脾益气，养肝生津，解酒解毒。用于久病体虚，脾虚食少，酒后烦渴以及免疫力低下。', '以上四味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.05~1.10（60℃）的清膏，滤过，滤液加入三氯蔗糖、苯甲酸钠适量，加水至1000ml，搅匀，即得。', '长沙南湖医院', '合剂', '合剂', 2, '邵阳制剂室', 2000.000, 25.062, 0.000, 25.062, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (166, 'Z02-W06-005', '补肺平喘合剂', '200ml/瓶', '委托加工', '每瓶装200ml（相当于中药饮片132g）', '湘药制备字Z20230848000', '补肺益肾，止咳平喘。用于肺肾不足、痰热阻肺所致的咳嗽气促、胸闷心悸、胸胁胀痛、吐痰黄稠等，以及慢性支气管炎，慢性阻塞性肺病、支气管哮喘、肺炎见上述证候者。', '以上十三味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.05～1.10（60℃）的清膏，滤过，滤液加入三氯蔗糖、苯甲酸钠适量，加水至1000ml，搅匀，即得。', '岳阳市中心医院', '合剂', '合剂', 2, '邵阳制剂室', 1000.000, 58.630, 0.000, 48.860, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (167, 'Z01-W05-001', '参芪四物颗粒', '12g/袋*9袋/盒', '委托加工', '"每袋装12g（每1g相当于饮片约 1.08g）"', '湘药制备字Z20230863000', '益气养血，补益肝肾，祛风除湿。用于体虚外感风寒湿邪所致倦怠乏力、腰腿酸痛，四肢麻木等，或腰椎间盘突出症，腰肌劳损，骨质增生，坐骨神经痛见上述证候者。', '以上十四味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精及蔗糖适量，混匀，制粒，干燥，制成1000g，即得。', '江华瑶族自治县民族中医医院', '颗粒剂', '颗粒剂', 5, '新邵制剂室', 2000.000, 44.790, 0.000, 44.790, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (168, 'Z01-W05-002', '芎参通络丸', '7g/袋*9袋/盒', '委托加工', '每袋装7g（每1g相当于饮片1g）', '湘药制备字Z20230877000', '活血行气，祛痰通络。用于气虚血瘀，痰湿阻络所致头晕目眩，乏力倦怠，胸闷胸痛等，或脑梗塞，脑供血不足，中风后遗症，冠心病，心率失常等见上述证候者。', '以上七味，粉碎成细粉，混匀，加入含4%炼蜜的水溶液制成水丸，干燥，打光，制成1000g，即得。', '江华瑶族自治县民族中医医院', '颗粒剂', '颗粒剂', 5, '新邵制剂室', 2000.000, 24.740, 0.000, 24.740, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (169, 'Z01-W05-003', '紫苏散寒颗粒', '10g/袋*9袋/盒', '委托加工', '"每袋装10g(（每1g相当于饮片约 1.33g）"', '湘药制备字Z20230862000', '芳香化湿，辟秽化浊，疏风解表。用于外感风寒、内伤湿滞、头痛昏重、身体困倦、脘闷纳呆。', '以上八味加水煎煮两次，提取挥发油，第一次煎煮1.5小时，第二次煎煮1小时，合并煎液，滤过，滤液浓缩至相对密度为1.25～1.30（60℃）的稠膏，加入糊精与蔗糖适量，混匀，制粒，干燥，均匀喷入上述挥发油，混匀，制成1000g，即得。', '江华瑶族自治县民族中医医院', '颗粒剂', '颗粒剂', 5, '新邵制剂室', 2000.000, 29.430, 0.000, 29.430, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
