INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (183, 'Z02-W13-004', '止痛消瘀散', '100g/袋', '委托加工', '100g/袋', '湘药制备字Z20200220000', '活血祛瘀，消肿止痛。用于跌打损伤、扭伤、瘀血肿痛等。', '以上十四味，干燥，粉碎成细粉，过筛，混匀，即得。', '祁阳市中医医院', '散剂', '散剂', 15, '邵阳制剂室', 1000.000, 17.300, 0.000, 17.300, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
