INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (195, 'Z02-W03-003', '地黄润肺合剂', '每瓶装200ml', '委托加工', '每瓶装200ml（每1ml相当于饮片约0.89g）', '湘药制备字Z20240932000', '养阴清热、润肺利咽。用于咽炎之虚火上炎证所致的咽喉干疼或灼热，有异物感、呛咳少痰或咳痰粘稠，口渴喜饮，饮量不多或受凉疲劳后症状加重，慢性咽炎见上述证候者。', '以上十二味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.05～1.10（60℃）的清膏，滤过，滤液加入三氯蔗糖、苯甲酸钠适量，加水至1000ml，搅匀，即得。', '津市市中医医院', '合剂', '合剂', 2, '邵阳制剂室', 1000.000, 28.062, 0.000, 28.062, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (196, 'Z02-W03-001', '麻黄散寒合剂', '每瓶装200ml', '委托加工', '每瓶装200ml（每1ml相当于饮片约1.23g）', '湘药制备字Z20240927000', '解表散寒、温肺化饮、止咳化痰。用于风寒犯肺致慢性咳嗽、咳痰、气短、呼吸困难、喘息、胸闷等症状者，慢性支气管炎、支气管哮喘、肺气肿，以及慢性支气管炎急性发作、肺炎、肺水肿、肺心病等见上述症状者。', '以上十三味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.10～1.15（60℃）的清膏，滤过，滤液加入三氯蔗糖、苯甲酸钠适量，加水至1000ml，搅匀，即得。', '津市市中医医院', '合剂', '合剂', 2, '邵阳制剂室', 1000.000, 27.280, 0.000, 27.280, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (197, 'Z01-W03-006', '参芎化瘀丸', '8g/袋×9袋/盒', '委托加工', '每袋装8g（每1g相当于饮片约1.96g）', '湘药制备字Z20240933000', '活血化瘀，消肿止痛。用于外伤气滞血瘀证所致的疼痛、肿胀、关节活动不利，关节肿痛等，跌打损伤、骨折脱位、肌肉劳损，急慢性扭挫伤见上述证候者。', '以上十六味，龙血竭、三七、醋延胡索、红花粉碎成细粉，灭菌，备用；其余丹参等十二味加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.30~1.35（60℃）的稠膏，加入上述细粉及糊精适量，混匀，制丸，干燥，打光，制成浓缩丸1000g，即得。', '津市市中医医院', '丸剂', '丸剂', 4, '新邵制剂室', 1000.000, 33.480, 0.000, 33.480, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (198, 'Z01-W03-007', '慈菇散结颗粒', '6g/袋×9袋/盒', '委托加工', '每袋装6g（每1g相当于饮片约2.17g）', '湘药制备字Z20240931000', '调和冲任，化痰散结。用于乳癖、乳核证属冲任失调证，因乳房痰浊凝结所致的乳中结核，形如丸卵，不疼痛，不发寒热，皮色不变，伴有月经失调。乳腺增生、乳腺结节见上述证候者。', '以上十味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精及三氯蔗糖适量，混匀，制粒，干燥，制成1000g，即得。', '津市市中医医院', '颗粒剂', '颗粒剂', 5, '新邵制剂室', 1000.000, 34.020, 0.000, 34.020, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (199, 'Z01-W03-008', '三七降脂胶囊', '80粒/瓶', '委托加工', '每粒装0.35g（每粒相当于饮片约0.33g）', '湘药制备字Z20240943000', '益气养阴、化浊降脂。用于气阴两虚夹瘀致胸闷刺痛，心悸不宁，自汗口渴，神疲乏力，或五心烦热，头晕眼花，舌红少苔，舌下有瘀点者。高脂血症、冠心病、高血压、代谢综合征等见上述证候者。', '以上四味，粉碎成细粉，灭菌，加入糊精适量，混匀，制粒，干燥，整粒，装入胶囊，制成1000粒，即得。', '津市市中医医院', '胶囊剂', '胶囊剂', 17, '新邵制剂室', 1000.000, 19.670, 0.000, 19.670, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (200, 'Z02-W01-001', '小儿咳停合剂', '60ml/瓶', '委托加工', '每瓶装60ml', '湘药制字Z20090902', '清热解毒，宣肺化痰，止咳平喘。用于治疗小儿上呼吸道感染、急性支气管炎证属痰热者。', '以上十味，加水煎煮二次，第一次2小时，第二次1.5小时，滤过，合并滤液，浓缩至相对密度约为1.15（60℃）的浸膏，加乙醇使含醇量为60%，静置12小时，取上清夜，滤过，滤液回收乙醇，浓缩至相对密度为1.08～1.10（60℃）的清膏，加入适量蔗糖与羟苯乙酯0.3g，煮沸，加水至1000ml，混匀，即得。', '怀化市第五人民医院', '合剂', '合剂', 2, '邵阳制剂室', 2000.000, 14.820, 0.000, 14.820, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (201, 'Z02-W01-002', '肤柏舒洗剂', '100ml/瓶', '委托加工', '100ml/瓶', '湘药制字Z20080710', '清热燥湿，杀虫止痒。用于妇女湿热带下，以及真菌性，非特异性阴道炎证属湿热者。', '以上八味，冰片、薄荷脑加乙醇适量使溶解备用；其余苦参等六味加水煎煮三次，第一次2小时，第二次1.5小时，第三次1小时，滤过，合并滤液，浓缩至相对密度1.18（40℃）的浸膏，加乙醇使含醇量达60%，静置24小时，取上清液，过滤，滤渣用60%乙醇洗涤2～3次，合并滤液，回收乙醇，浓缩至相对密度为1.05（40℃）的浸膏，加入上述备用溶液，加水至1000ml，即得。', '怀化市第五人民医院', '洗剂', '洗剂', 14, '邵阳制剂室', 1500.000, 21.240, 0.000, 21.240, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (202, 'Z01-W24-001', '红花酊', '每瓶装50ml', '委托加工', '每瓶装50ml', '湘药制备字 Z20220588000', '活血祛瘀，消肿止痛。用于瘀血阻滞所致的跌打损伤，症见皮肤青紫瘀斑、肿胀疼痛、活动受限；软组织损伤见上述证候者。', '以上六味，粉碎成粗粉，混匀，用75%乙醇作溶剂，浸渍24小时后，缓缓渗漉，收集渗漉液，滤过，加75%乙醇调至1000ml,搅匀，静置，滤过，分装，即得。', '冷水江市中医医院', '酊剂', '酊剂', 12, '新邵制剂室', 2000.000, 18.530, 21.300, 8.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (203, 'Z01-W24-002', '栀黄止痛散', '每袋装100g', '委托加工', '每袋装100g', '湘药制备字 Z20220587000', '活血祛瘀，消肿止痛，祛风除湿。用于瘀血阻络所致的跌打损伤、痹病，症见瘀血疼痛或关节疼痛、肿胀、活动受限或屈伸不利；软组织损伤、风湿性关节炎、类风湿关节炎见上述证候者。', '以上二十一味，粉碎成最细粉，过筛，混匀，灭菌，干燥，制成约1000g,即得。', '冷水江市中医医院', '散剂', '散剂', 15, '新邵制剂室', 1000.000, 30.960, 35.600, 22.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (204, 'Z02-W22-001', '化痰通络合剂', '每瓶装 200ml', '委托加工', '每瓶装200ml（每1ml相当于饮片0.72g）', '湘药制备字 Z20240934000', '疏肝健脾，化痰祛湿。用于肝郁脾虚、痰湿阻络所致胁肋疼痛，头痛目眩，眩晕，头重如蒙，或伴视物旋转，胸闷恶心，呕吐痰涎，纳呆，舌苔白腻，脉濡滑，或良性位置性眩晕、后循环缺血、梅尼埃病、高血压病等见上述证候者。', '以上十六味，加水煎煮两次，第一次1.5小时，第二次 1小时，合并煎液，滤过，滤液浓缩至相对密度为1.05～1.10(60℃) 的清膏，滤过，滤液加入三氯蔗糖、苯甲酸钠适量，加水至1000ml,搅匀，即得。', '隆回县中医医院', '合剂', '合剂', 2, '邵阳制剂室', 1000.000, 57.070, 0.000, 41.088, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (205, 'Z01-W22-001', '化瘀止痛丸', '5g/袋×9袋/盒', '委托加工', '"每袋装5g（每1g相当于饮片 2.25g）"', '湘药制备字 Z20240967000', '活血止血、化瘀消肿、行气止痛，用于情志不遂、外邪侵袭、跌仆外伤所致胸胁胀闷、瘀肿刺痛、舌紫暗及脉涩，或跌打损伤、骨折等见上述证候者。', '以上十三味，醋延胡索、三七、龙血竭、红花粉碎成细粉，灭菌，备用；其余姜黄等九味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.25～1.30(60℃)的稠膏，加入上述细粉及糊精适量，混匀，制丸，打光，干燥，制成浓缩丸1000g, 即得。', '隆回县中医医院', '丸剂', '丸剂', 4, '新邵制剂室', 2000.000, 51.860, 0.000, 37.338, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (206, 'Z01-W22-002', '理脾接骨丸', '5g/袋×9袋/盒', '委托加工', '每袋装5g（每1g相当于饮片约1.69g）', '湘药制备字 Z20240953000', '强筋健骨，补脾益肾。用于骨断筋伤，脾肾亏虚所致局部疼痛，压痛，肿胀，瘀斑，或腰膝酸软，脐腹隐痛，腹泻，纳呆，头晕，耳鸣，面色晦黄或黯，舌质淡胖或暗，脉细弱。或骨折后期、恢复期治疗。', '以上十八味，烫骨碎补、龙血竭、当归、红花、赤芍、茯苓、川木香、肉桂粉碎成细粉，灭菌，备用；其余土鳖虫等十味加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.20～1.25(60℃)的稠膏，加入上述细粉及糊精适量，混匀，制丸，打光，干燥，制成浓缩丸1000g, 即得。', '隆回县中医医院', '丸剂', '丸剂', 4, '新邵制剂室', 2000.000, 51.110, 0.000, 36.798, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (207, 'Z01-W22-003', '通痹除湿止痛膏', '6g/贴*2贴/袋*3袋/盒', '委托加工', '每贴净重6g（每1g相当于饮片约0.23g）', '湘药制备字Z20240955000', '祛风除湿，通络止痛。用于风寒湿痹所致诸身手足疼痛，肢体困重，头痛如裹，舌质紫暗，舌苔薄白或腻，脉濡细，或肩周炎、颈椎病、腰椎间盘突出症等见上述证候者。', '以上十五味，细辛、醋没药、醋乳香粉碎成细粉，与樟脑、天然冰片配研成细粉，备用；其余十味药与麻油1000g 置锅内浸渍24小时，炸至药材内部焦褐色，弃渣，滤过，炼油至滴水成珠。加入铅丹320g～400g, 搅匀，收膏，浸膏、取膏，用文火熔化，加入上述细粉，搅匀，制成1000g,分摊，即得。', '隆回县中医医院', '黑膏药', '黑膏药', 132, '新邵制剂室', 2000.000, 39.933, 0.000, 28.752, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (208, 'Z02-W22-002', '七味接骨胶囊', '每瓶装84粒', '委托加工', '每粒装 0.35g', '湘药制备字 Z20241010000', '活血化瘀，续筋接骨。用于筋伤骨断所致骨断，骨 碎，骨歪，患处肿胀，疼痛，活动障碍，或跌打损伤，骨折中期见上 述证候者。', '以上七味，粉碎成细粉，灭菌，制粒，干燥，整粒， 装入胶囊，制成1000粒，即得。', '隆回县中医医院', '胶囊剂', '胶囊剂', 17, '邵阳制剂室', 2000.000, 32.900, 0.000, 23.688, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (209, 'Z04-001', '归芪精口服液', '10ml/支', '自主加工', '10ml/支*10瓶', '湘药制字Z20080624', '补气生血、固本止汗、活血调经、托毒生肌。', '以上两味 ,加水煎煮二次，第一次2小时，第二次1.5小时，煎液滤过，合并滤液，滤液浓缩至相对密度1.20-1.30（40℃）的稠膏，加乙醇至含醇量达到70%，搅匀，静置48小时，取上清液备用；残渣再加1倍量的70%乙醇，搅匀，静置72小时，取上清液，与备用上清液合并，滤过，回收乙醇至相对密度为1.15-1.20（40℃），加蔗糖100g,苯甲酸钠2.5使其溶解，加水至1000ml,灭菌，既得。', '耒阳市中医医院', '合剂', '合剂', 2, '耒阳制剂室', 2500.000, 0.000, 0.000, 42.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (210, 'Z04-003', '降酶丸', '每10丸得1.37g(每1g相当于饮片0.78g)', '自主加工', '36g/瓶*1瓶/盒', '湘药制备字Z20241019000', '活血疏肝，清热解毒。', '以上四味，粉碎成细粉，灭菌，混匀。每100g粉末用炼蜜40g与水50g制成水蜜丸，打光，干燥，制成1000g，即得。', '耒阳市中医医院', '丸剂', '丸剂', 4, '耒阳制剂室', 2000.000, 31.000, 31.000, 31.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (211, 'Z04-004', '消肿止痛丸', '每10丸重1.32g ( 每 1g 相当于饮片约0.78g)', '自主加工', '36g/瓶*1瓶/盒', '湘药制备字 Z20241096000', '活血祛瘀，行气止痛', '以上十味，粉碎成细粉，灭菌，混匀。每100g粉末用炼 蜜40g与水50g制成水蜜丸，打光，干燥，制成1000g,即得。', '耒阳市中医医院', '丸剂', '丸剂', 4, '耒阳制剂室', 3000.000, 0.000, 29.000, 29.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (212, 'Z04-005', '乙肝丸', '每10丸重1.31g  ( 每 1g 相当于饮片约0.76g)', '自主加工', '36g/瓶*1瓶/盒', '湘药制备字 Z20241020000', '健脾益肾，解毒祛湿', '以上十味，粉碎成细粉，灭菌，混匀。每100g粉末用炼蜜40g与水50g制成水蜜丸，打光，干燥，制成1000g，即得。', '耒阳市中医医院', '丸剂', '丸剂', 4, '耒阳制剂室', 700.000, 29.000, 29.000, 29.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (213, 'Z02-W02-002', '射麻咳喘合剂', '200ml/瓶', '委托加工', '每瓶装200ml（每1ml相当于饮片0.95g）', '湘药制备字Z20230905000', '宣肺化痰，降气定喘。用于痰饮郁结，气逆咳喘所致咳喘、咳痰、胸脘痞闷不舒等，以及哮喘、支气管哮喘见上述证候者。', '以上十七味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.05～1.10（60℃）的清膏，滤过，滤液加入三氯蔗糖、苯甲酸钠适量，加水至1000ml，搅匀，即得。', '安化县中医医院', '合剂', '合剂', 2, '邵阳制剂室', 1000.000, 46.500, 0.000, 46.500, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (214, 'Z02-W02-003', '银花解毒洗液', '200ml/瓶', '委托加工', '每瓶装200ml（每1ml相当于饮片约0.74g）', '湘药制备字Z20230904000', '清热祛湿、杀虫止痒。用于湿热蕴肤、风湿毒聚证所致全身或局部皮肤灼热瘙痒、红斑、丘疹、伴或不伴色素沉着和苔藓样变等，以及皮肤瘙痒、疥疮、癣、湿疹见上述症状者。', '以上十三味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.05～1.10（60℃）的清膏，滤过，加入苯甲酸钠适量，加水至1000ml，搅匀，即得。', '安化县中医医院', '洗剂', '洗剂', 14, '邵阳制剂室', 1000.000, 31.000, 0.000, 31.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (215, 'Z02-W02-001', '辛苍鼻炎合剂', '200ml/瓶', '委托加工', '每瓶装200ml（每1ml相当于饮片1.01g）', '湘药制备字Z20240952000', '疏风通窍，清热化浊。用于外感风热或外感风寒郁久化热，上犯鼻窍，而见鼻塞，流黄浊涕或粘白色鼻涕，或伴头痛，咳嗽，咯黄、白浓痰等症。慢性鼻炎、鼻窦炎及上呼吸道感染见上述症状者。', '以上十四味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.05～1.10（60℃）的清膏，滤过，滤液加入三氯蔗糖、苯甲酸钠适量，加水至1000ml，搅匀，即得。', '安化县中医医院', '合剂', '合剂', 2, '邵阳制剂室', 1000.000, 39.000, 0.000, 39.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (216, 'Z01-W06-003', '肾复康颗粒', '8g/袋*6袋/盒', '委托加工', '每袋装8g（相当于中药饮片22.5g）', '湘药制备字Z20230847000', '益气养阴，清利湿热，解毒消肿。适用于气阴不足、湿蕴下焦所致浮肿、腰痛、舌苔黄腻等，肾病综合症、慢性肾炎、急性肾炎恢复期、慢性肾盂肾炎、慢性肾功能不全见上述证候者。', '以上十六味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入三氯蔗糖及糊精适量，混匀，制粒，干燥，制成1000g，即得。', '岳阳市中心医院', '颗粒剂', '颗粒剂', 5, '新邵制剂室', 1000.000, 56.580, 0.000, 47.150, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (217, 'Z01-W06-004', '通络止痛酊', '100ml/瓶', '委托加工', '每瓶装 100ml(每 1ml 相当于饮片约0.21g）', '湘药制备字Z20240970000', '温经散寒，消肿止痛。用于风寒湿邪痹阻经络所致关节、肌肉、筋骨局部疼痛或酸痛、肢体麻木，屈伸不利、关节僵硬或肿大等，以及风湿、类风湿性骨关节炎、颈腰椎疾病、肩周炎等见上述证候者。', '以上十七味，除冰片、薄荷脑外，其余十五味粉碎成最粗粉，用70%乙醇浸渍两次，第一次浸渍5日，第二次浸渍1 日，滤过，合并滤液，加入冰片、薄荷脑，搅匀使溶解，静置，取上清液，用70%乙醇调整至1000ml,搅匀，即得。', '岳阳市中心医院', '酊剂', '酊剂', 12, '新邵制剂室', 1000.000, 37.750, 0.000, 31.460, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (218, 'Z01-W06-005', '洋参三七胶囊', '60粒/瓶', '委托加工', '每粒装 0.3g(相当于中药饮片0.3g）', '湘药制备字 Z20230844000', '益气活血，化瘀通络。用于气滞血瘀或瘀阻脑络所 致胸痹心痛、眩晕、胸闷刺痛、心悸不宁、痴呆健忘、耳鸣、肢麻神疲等，以及冠心病、脑动脉硬化或中风后遗证见上述证候者。', '以上十味，粉碎成细粉，制粒，干燥，整粒，装入胶囊，制成1000粒，即得。', '岳阳市中心医院', '胶囊剂', '胶囊剂', 17, '新邵制剂室', 1000.000, 59.000, 0.000, 49.160, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (219, 'Z01-W06-006', '葛根通络丸', '5g*9袋/盒', '委托加工', '每袋装 5g(每1g相当于饮片 2g）', '湘药制备字Z20240996000', '活血通络，散风止痛 。用于血瘀气滞、风湿痹阻所致头晕、颈项僵硬、肩背酸痛、四肢麻木、关节活动受限等， 颈肩腰膝等关节退行性病变及各类骨关节病见上述证候者。', '以上十四味，骨碎补、红花、白芍、醋延胡索粉碎成细粉，灭菌，备用；其余葛根等十味加水煎煮两次第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.30～1.35(60℃)的稠膏，加入上述细粉及糊精适量，混匀，制丸，干燥，打光，制成浓缩丸1000g,即得。', '岳阳市中心医院', '丸剂', '丸剂', 4, '新邵制剂室', 1000.000, 52.680, 0.000, 46.900, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (220, 'Z01-W06-007', '健脾益气丸', '10g*6袋/盒', '委托加工', '每袋装 10g（每1g相当于饮片0.9g）', '湘药制备字 Z20240997000', '健脾益气，和胃消食。主要用于脾胃虚弱 、运化失常所致面恍白或萎黄、神疲乏力、纳差食少、食后腹胀、呕吐、呃逆、自汗、便溏、舌淡胖有齿印、苔白、脉细无力等，以及胃炎 、胃溃疡见上述证候者。', '以上十味，粉碎成细粉，灭菌，混匀，加入糊精适量，混匀，加水制丸，干燥，打光，制成1000g, 即得。', '岳阳市中心医院', '丸剂', '丸剂', 4, '新邵制剂室', 1000.000, 60.480, 0.000, 50.400, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (221, 'Z02-W01-003', '活血溶栓胶囊', '24粒/盒', '委托加工', '每粒装0.5g', '湘药制字Z20080711', '活血化瘀，通脉降浊，用于淤血痰浊，阻滞经脉所致头晕沉，胸闷，身重，健忘，面垢，舌淡紫有瘀斑，脉涩等高脂血症、高黏血症及脑动脉硬化见上述症状者。', '以上四味，三七，水蛭粉碎成细粉，备用；银杏叶、丹参加水煎煮二次，第一次2小时，第二次1.5小时，合并滤液，滤过，滤液浓缩至相对密约为1.15（40℃）的浸膏，加乙醇使含醇量达60%，静置12小时，取上清液，滤过，滤液回收乙醇，浓缩至相对密度为1.30～1.35（60℃）的稠膏，加入上述细粉，混匀，干燥，粉碎成细粉，装入胶囊，制成1000粒，即得。', '怀化市第五人民医院', '胶囊剂', '胶囊剂', 17, '邵阳制剂室', 6000.000, 17.560, 29.260, 17.560, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (222, 'Z01-W01-001', '利咽清热颗粒', '15g*10袋/盒', '委托加工', '15g/袋', '湘药制字Z20080846', '清热解毒，利咽消肿，生津止渴。用于热毒伤阴所致咽喉肿痛，口渴等症。', '以上十味，加水煎煮三次，第一次2小时，第二次1.5小时，第三次1小时，煎液滤过，滤液合并，滤液浓缩至相对密度1.30～1.35（60℃）的稠膏，加入适量蔗糖粉，混匀，制成颗粒，干燥，制成1000g，即得。', '怀化市第五人民医院', '颗粒剂', '颗粒剂', 5, '新邵制剂室', 2000.000, 19.320, 32.200, 19.320, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (223, 'Z01-W01-002', '山菊抗病毒颗粒', '10g*10袋/盒', '委托加工', '10g/袋', '湘药制字Z20080845', '辛凉解表，清热解毒，利咽消肿。用于外感风热所致咽喉肿痛等症，上呼吸道感染见上述证候者.', '以上十一味，加水煎煮二次，第一次浸泡30分钟，煎煮2小时；第二次1.5小时，煎液滤过，合并滤液，静置12小时，取上清液，滤过，滤液浓缩至相对密度约为1.20（60℃）的浸膏，加乙醇使含醇量达60%，静置12小时，取上清夜，滤过，滤液回收乙醇，并浓缩至相对密度为1.30～1.35（60℃）的稠膏，加入蔗糖适量，混匀，制成颗粒，干燥，制成颗粒1000g，即得。', '怀化市第五人民医院', '颗粒剂', '颗粒剂', 5, '新邵制剂室', 2000.000, 18.300, 0.000, 18.300, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (224, 'Z04-W27-001', '舒筋活血止痛酊', '100ml/瓶', '委托加工', '100ml/瓶', '湘药制字Z20080882', '舒筋活血，祛风除湿，化瘀止痛。用于软组织损伤，腰椎骨关节炎，风湿性关节炎，骨折后期疼痛等证属风湿或瘀血阻络者。', '以上十味，除樟脑外，其余当归等九味，加75％乙醇875ml，搅拌，密闭浸溃3个月，前半月每日搅拌1次，以后每周搅拌1次，倾取上清液。药渣压榨取液与上清液合并，静置3日，滤过，滤液加樟脑搅拌使溶解，加水使成 1000 ml，分装，即得。', '张家界市中医医院', '酊剂', '酊剂', 12, '耒阳制剂室', 2000.000, 19.680, 0.000, 19.680, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (225, 'Z01-W29-001', '参连清胃颗粒', '8g*6袋/盒', '委托加工', '每袋装8g（每1g相当于饮片约2.33g）', '湘药制备字Z20241044000', '清热祛湿，化瘀止痛，健脾益胃。用于脾胃气虚，湿热瘀滞所致胃脘疼痛，口苦口干，腹胀便溏，食欲不振，神疲倦怠，舌暗红或淡红有瘀斑、瘀点，慢性浅表性胃炎、胃溃疡见上述证候者。', '以上十一味，加水煎煮两次，第一次2.0小时，第二次1.5小时，滤过，合并滤液，滤液浓缩至相对密度约为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精、三氯蔗糖适量，混匀，制粒，干燥，制成1000g，即得。', '娄底健缘中医医院', '颗粒剂', '颗粒剂', 5, '新邵制剂室', 1500.000, 27.000, 0.000, 27.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (226, 'Z01-W29-002', '丹参心脑宁丸', '10g*6袋', '委托加工', '每袋装10g（每1g相当于饮片约1.54g）', '湘药制备字Z20241036000', '益气养阴，活血化瘀，疏通脉络。适用于气滞血瘀所致胸痹，头痛，眩晕，症见：胸闷刺痛，心悸不宁，头晕目眩，冠心病、脑动脉硬化见上述症状者。', '以上十三味，人参、三七、红花、冰片粉碎成细粉，备用；其余丹参等九味加水煎煮两次，第一次1.5小时，第二次1.0小时，合并煎液，滤过，滤液浓缩至相对密度为1.30～1.35（60℃）的稠膏，加入上述细粉及糊精适量，混匀，制丸，干燥，打光，制成浓缩丸1000g，即得。', '娄底健缘中医医院', '丸剂', '丸剂', 4, '新邵制剂室', 1500.000, 21.000, 0.000, 21.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (227, 'Z01-W29-003', '葛根颈腰止痛丸', '10g*6袋/盒', '委托加工', '每袋装10g（每1g相当于饮片约2.4g）', '湘药制备字Z20241035000', '补肝益肾，活血止痛。用于肝肾亏虚、血瘀气滞所致颈项僵硬、疼痛，腰背酸痛，手臂麻木，活动困难；颈椎病、腰间盘突出见上述证候者。', '以上十四味药，骨碎补、延胡索、白芍粉碎成细粉，灭菌，备用；其余葛根等十一味加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.30~1.35（60℃）的稠膏，加入与上述细粉及糊精适量，混匀，制丸，打光，干燥，制成浓缩丸1000g，即得。', '娄底健缘中医医院', '丸剂', '丸剂', 4, '新邵制剂室', 1500.000, 22.000, 0.000, 22.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (228, 'Z01-W29-004', '活络壮骨颗粒', '6g*9袋/盒', '委托加工', '每袋装6g（每1g相当于饮片约1.67g）', '湘药制备字Z20241040000', '补益肝肾，强筋壮骨，活络止痛。用于肝肾不足、经络痹阻所致的骨脆易折、腰酸膝软、腰背四肢关节疼痛、畏寒肢冷或抽筋、下肢无力，骨折后期或骨痿、退行性骨关节病见上述证候者。', '以上十四味，鹿茸片粉碎成细粉，灭菌，备用。其余熟地黄等十三味加水煎煮二次，第一次煎煮2小时，第二次煎煮1.5小时，滤过，合并滤液，浓缩至相对密度约为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入鹿茸粉、糊精与三氯蔗糖适量，混匀，制粒，干燥，制成1000g，即得。', '娄底健缘中医医院', '丸剂', '丸剂', 4, '新邵制剂室', 1500.000, 29.000, 0.000, 29.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (229, 'Z01-W29-005', '三七止痛丸', '8g*6袋/盒', '委托加工', '每袋装8g（每1g相当于饮片约2.13g）', '湘药制备字Z20241039000', '散瘀止血，消肿止痛。用于血瘀气滞所致的疼痛、肿胀、关节活动不利，跌打损伤，骨折脱位，关节肿痛，肌肉劳损，急慢性扭挫伤见上述证候者。', '以上十六味，三七、龙血竭、红花、延胡索粉碎成细粉，备用；其余桃仁等十二味加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.30~1.35（60℃）的稠膏，加入上述细粉及糊精适量，混匀，制丸，干燥，打光，制成浓缩丸1000g，即得。', '娄底健缘中医医院', '丸剂', '丸剂', 4, '新邵制剂室', 1500.000, 23.000, 0.000, 23.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (230, 'Z01-W29-006', '双黄养阴颗粒', '8g*6袋/盒', '委托加工', '每袋装8g（每1g相当于饮片约1.75g）', '湘药制备字Z20241038000', '清热利湿，活血解毒，益气养阴。适用于慢性肾炎之气阴两虚，瘀毒互结所致神疲乏力，口燥咽干；面色无华，手足心热，腰膝酸软，腰痛固定或刺痛，咽喉肿痛，舌质淡红或偏红或暗红，苔薄白或薄黄或少苔，脉细或弱或细涩，急、慢性肾功能衰竭、氮质血症、尿毒症及血尿素氮升高等见上述症状者。', '以上十二味，加水煎煮二次，第一次2小时，第二次1.5小时，合并煎液，滤过，滤液减压浓缩至相对密度约为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精、三氯蔗糖适量，混匀，制粒，干燥，制成1000g，即得。', '娄底健缘中医医院', '颗粒剂', '颗粒剂', 5, '新邵制剂室', 1500.000, 18.000, 0.000, 18.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (231, 'Z01-W29-007', '洋参养心胶囊', '0.3g*24粒/盒', '委托加工', '每粒装0.3g（每1粒相当于饮片约0.29g）', '湘药制备字Z20241042000', '益气养阴，化瘀通络。用于气虚血瘀所致胸痹心痛，困倦乏力，心悸不宁，头晕目眩等，以及冠心病、脑动脉硬化、高血脂见上述症状者。', '以上四味，粉碎成细粉，灭菌，加入淀粉适量，混匀，制粒，干燥，整粒，装入胶囊，制成1000粒，即得。', '娄底健缘中医医院', '胶囊剂', '胶囊剂', 17, '新邵制剂室', 5000.000, 8.000, 0.000, 8.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (232, 'Z01-W29-008', '茵陈胆宁丸', '8g*6袋/盒', '委托加工', '每袋装8g（每1g相当于饮片约3.38g）', '湘药制备字Z20241037000', '清热利胆，利湿排石。用于湿热熏蒸所致的腹痛、发热、黄疸，甚则右上腹绞痛，急性胆囊炎，胆石症，胆囊折叠，手术后的肝胆管、胆总管结石见上述症状者。', '以上十二味，茯苓、延胡索粉碎成细粉，灭菌，备用；其余茵陈等十味加水煎煮二次，第一次煎煮1.5小时，第二次煎煮1.0小时，合并煎液，滤过，滤液浓缩至相对密度为1.30~1.35（60℃）的稠膏，加入上述细粉与糊精适量，混匀，制丸，打光，干燥，制成浓缩丸1000g，即得。', '娄底健缘中医医院', '丸剂', '丸剂', 4, '新邵制剂室', 1500.000, 25.000, 0.000, 25.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (233, 'Z02-W29-001', '麻黄止咳合剂', '200ml/瓶', '委托加工', '每瓶装200ml（每1ml相当于饮片1.38g）', '湘药制备字Z20241043000', '祛风化痰，止咳平喘。用于风邪犯肺所致的咳嗽、咳痰反复发作，支气管炎、慢性阻塞性肺疾病见上述证候者。', '以上九味，加水煎煮两次，第一次煎煮2小时，第二次煎煮1.5小时，合并滤液，滤过，浓缩至相对密度为1.15～1.20（60℃）的清膏，滤过，滤液加入三氯蔗糖、苯甲酸钠适量，加水至1000ml，搅匀，即得。', '娄底健缘中医医院', '合剂', '合剂', 2, '邵阳制剂室', 1500.000, 37.000, 0.000, 37.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (234, 'Z02-W29-002', '清热排毒合剂', '200ml/瓶', '委托加工', '每瓶装200ml（每1ml相当于饮片约1.01g）', '湘药制备字Z20241041000', '疏风宣肺、清热解毒、利咽消肿。用于热毒壅盛所致发热面赤，烦躁口渴，咽喉肿痛，流感、上呼吸道感染见上述症状者。', '以上十二味，加水煎煮两次，第一次1.5小时，第二次1.0小时，合并煎液，滤过，滤液浓缩至相对密度为1.10～1.15（60℃）的清膏，滤过，滤液加入三氯蔗糖与苯甲酸钠适量，加水至1000ml，搅匀，分装，即得。', '娄底健缘中医医院', '合剂', '合剂', 2, '邵阳制剂室', 1500.000, 29.000, 0.000, 29.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (235, 'Z01-W03-011', '清热排石颗粒', '6g/袋*8袋/盒', '委托加工', '每袋装6g（每1g相当于饮片约3.17g）', '湘药制备字Z20240942000', '清热利尿，通淋排石。湿热久蕴下焦致尿中时夹砂石，小便艰涩，或排尿时突然中断，尿道窘迫疼痛，少腹拘急，或腰腹绞痛难忍，痛引少腹，连及外阴，尿中带血，舌红，苔薄黄。肾结石、输尿管结石、膀胱结石、尿道结石等泌尿系统结石症见上述症状者。', '以上九味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精及三氯蔗糖适量，混匀，制粒，干燥，制成1000g，即得。', '津市市中医医院', '颗粒剂', '颗粒剂', 5, '新邵制剂室', 1500.000, 29.660, 0.000, 29.660, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (236, 'Z01-W03-010', '白芍止痛颗粒', '8g/袋*9袋/盒', '委托加工', '每袋装8g（每1g相当于饮片约2.46g）', '湘药制备字Z20240929000', '补益肝肾、活血化瘀、行气止痛。用于腰痛之肝肾不足、气滞血瘀所致的腰腿部疼痛或酸胀痛、活动受限、麻木、乏力等，各类腰椎病、腰肌劳损等见上述证候者。', '以上十四味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精及三氯蔗糖适量，混匀，制粒，干燥，制成1000g，即得。', '津市市中医医院', '颗粒剂', '颗粒剂', 5, '新邵制剂室', 1000.000, 38.490, 0.000, 38.490, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (237, 'Z01-W03-009', '牡丹明目颗粒', '13g/袋*6袋/盒', '委托加工', '每袋装13g（每1g相当于饮片约2.15g）', '湘药制备字Z20240928000', '疏肝理气、滋阴养目。用于干眼症证属肝气郁结证所致的视力疲劳、涩痒不适、畏光、心情不舒、睡眠不佳等角结膜干燥症见上述证候者。', '以上十四味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.25～1.30（60℃）的稠膏，干燥，粉碎，加入糊精及三氯蔗糖适量，混匀，制粒，干燥，制成1000g，即得。', '津市市中医医院', '颗粒剂', '颗粒剂', 5, '新邵制剂室', 1000.000, 38.260, 0.000, 38.260, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
