INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (300, 'Z01-028', '益气养心膏（制剂）', '每袋装20g（每1g相当于饮片1.4g）', '自主加工', '每盒装15袋', '湘药制备字Z20241093000', '益气养心，活血通脉。用于气血亏虚、心脉痹阻所致头晕、心悸、胸痛、胸闷、少气懒言、神疲乏力、食欲不振，冠心病、心绞痛等见上述证候者。', '以上二十味，阿胶粉碎成最粗粉，备用；其余黄芪等十九味，加水煎煮两次，第一次2小时，第二次1.5小时，合并煎液，滤过，滤液浓缩至相对密度为1.25～1.30（60℃）的清膏，取蜂蜜适量加热制成1.28~1.30（60℃）的炼蜜，加入上述清膏、阿胶最粗粉、木糖醇、甜菊糖苷及苯甲酸钠适量，加热使溶化，混匀，浓缩至相对密度1.30~1.35（60℃），制成1000g，即得。', '新邵县中医医院', '膏方', '膏方', 7, '新邵制剂室', 240.000, 0.000, 450.000, 0.000, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (301, 'Z04-W10-01', '五味护肝丸', '每袋装 8g（每 1g 相当于饮片约 1.33g）', '委托加工', '8g/袋/9袋/盒', '湘药制备字 Z20241119000', '解毒舒肝，健脾化湿。用于肝瘀湿滞，临床症见肝区热痛，腹水，全身乏力，口苦咽干，头晕耳鸣。急慢性肝炎，脂肪性肝炎、肝损伤，肝硬化，腹水，肝胆占位性病变，血吸虫病，肝功能损伤所致上述证候者。', '以上十六味，五味子、虎杖、土茯苓、白术、丹参、桃仁、猪苓、炙黄芪、三七粉碎成细粉，灭菌，备用。其余垂盆草等七味，加水煎煮两次，第一次提取1.5小时，第二次提取1.0小时，滤过，合并滤液，滤液浓缩至相对密度约为1.10~1.15（60℃）的稠膏，加入上述细粉及糊精适量，混匀，制软材，制丸，打光，干燥，制得1000g，即得。', '华容县中医医院', '丸剂', '丸剂', 4, '耒阳制剂室', 2000.000, 43.401, 0.000, 43.401, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (302, 'Z04-W10-02', '益气养血丸', '每袋装 8g（每 1g 相当于饮片 1.5g）', '委托加工', '8g/袋*9袋/盒', '湘药制备字 Z20241106000', '益气养血，活血通络，止痛。用于气血失养，筋脉阻滞所致的局部或筋骨肌肉麻木、疼痛。关节炎、肩周炎、颈椎病、腰椎间盘突出症、骨折、跌打损伤，糖尿病、糖尿病溃疡见上述证候者。', '以上十六味，白芍、牛膝、桂枝、醋乳香、醋没药、川芎、延胡索、赤芍、牡丹皮粉碎成细粉，灭菌，备用；其余炙黄芪等七味，加水煎煮两次，第一次1.5小时，第二次1小时，合并煎液，滤过，滤液浓缩至相对密度为1.15～1.20（60℃）的稠膏，加入上述细粉及糊精适量，混匀，制丸，打光，干燥，制成浓缩丸1000g，即得。', '华容县中医医院', '丸剂', '丸剂', 4, '耒阳制剂室', 1000.000, 45.968, 0.000, 45.968, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
INSERT INTO preparation (preparation_id, preparation_code, preparation_name, spec, process_attr, package_spec, record_info, function_main, method, unit_name, dosage_category, dosage_name, dosage_form_id, producer, batch_qty, invoice_price, insurance_price, settlement_price, retail_price, sales_price, status, is_deleted, version, created_by, updated_by, created_time, updated_time) VALUES (303, 'Z04-W10-03', '滋肾壮骨丸', '每袋装 8g（每 1g 相当于饮片约 0.73g）', '委托加工', '8g/袋*9袋/盒', '湘药制备字 Z20241107000', '滋补肝肾，健骨止痛。用于肝肾亏虚所致关节疼痛、僵硬，肢体麻木或痉挛，腰膝酸软，头晕，耳鸣，嗜睡、乏力等。骨折后期、骨质疏松、颈肩腰膝等关节退行性病变及各类骨关节病、骨折中后期、骨关节病见上述证候者。', '以上十味，粉碎成细粉，灭菌，混匀，加糊精适量，混匀，加水适量，混匀，制丸，抛光，干燥，制成1000g，即得。', '华容县中医医院', '丸剂', '丸剂', 4, '耒阳制剂室', 1000.000, 47.209, 0.000, 47.209, 0.000, 0.000, 1, 0, 1, 1, 1, NOW(), NOW());
